const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(
    new Cesium.OpenStreetMapImageryProvider({
      url: 'https://tile.openstreetmap.org/',
      maximumLevel: 18,
    })
  ),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;

// Define the three Florida region polygons
const panhandle = viewer.entities.add({
  name: 'Panhandle',
  polygon: {
    hierarchy: new Cesium.PolygonHierarchy(
      Cesium.Cartesian3.fromDegreesArray([
        -87.0, 30.0,
        -85.0, 30.0,
        -85.0, 31.0,
        -87.0, 31.0,
      ])
    ),
    material: Cesium.Color.DODGERBLUE.withAlpha(0.6),
    outline: true,
    outlineColor: Cesium.Color.WHITE,
    outlineWidth: 2,
  },
});

const central = viewer.entities.add({
  name: 'Central',
  polygon: {
    hierarchy: new Cesium.PolygonHierarchy(
      Cesium.Cartesian3.fromDegreesArray([
        -82.0, 27.5,
        -80.5, 27.5,
        -80.5, 29.0,
        -82.0, 29.0,
      ])
    ),
    material: Cesium.Color.LIMEGREEN.withAlpha(0.6),
    outline: true,
    outlineColor: Cesium.Color.WHITE,
    outlineWidth: 2,
  },
});

const keys = viewer.entities.add({
  name: 'Keys',
  polygon: {
    hierarchy: new Cesium.PolygonHierarchy(
      Cesium.Cartesian3.fromDegreesArray([
        -82.0, 24.5,
        -80.0, 24.5,
        -80.0, 25.5,
        -82.0, 25.5,
      ])
    ),
    material: Cesium.Color.CRIMSON.withAlpha(0.6),
    outline: true,
    outlineColor: Cesium.Color.WHITE,
    outlineWidth: 2,
  },
});

// Store original materials keyed by entity id
const originalMaterials = {
  [panhandle.id]: Cesium.Color.DODGERBLUE.withAlpha(0.6),
  [central.id]: Cesium.Color.LIMEGREEN.withAlpha(0.6),
  [keys.id]: Cesium.Color.CRIMSON.withAlpha(0.6),
};

// Hover state
let hoveredEntity = undefined;

const handler = new Cesium.ScreenSpaceEventHandler(viewer.scene.canvas);

handler.setInputAction((movement) => {
  // Restore previous highlighted entity
  if (Cesium.defined(hoveredEntity)) {
    hoveredEntity.polygon.material = originalMaterials[hoveredEntity.id];
    hoveredEntity = undefined;
  }

  const picked = viewer.scene.pick(movement.endPosition);

  if (
    Cesium.defined(picked) &&
    Cesium.defined(picked.id) &&
    Cesium.defined(picked.id.polygon)
  ) {
    hoveredEntity = picked.id;
    hoveredEntity.polygon.material = Cesium.Color.YELLOW;
  }
}, Cesium.ScreenSpaceEventType.MOUSE_MOVE);

// Frame camera over Florida
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-83.0, 27.5, 1500000),
  orientation: {
    heading: Cesium.Math.toRadians(0),
    pitch: Cesium.Math.toRadians(-90),
    roll: 0,
  },
});
